<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { getAccountList } from '@/api/account'
import { createProductBatch, getProductBatches, getProductMatrixDetail, getSavedProductFilters, newRequestId, previewProductBatch, queryProductMatrix, saveProductFilter, type MatrixProduct, type ProductBatchRequest, type ProductFilter } from '@/api/matrix'
import type { Account } from '@/types'
import { showError, showSuccess } from '@/utils'
import { useModalFocusTrap } from '@/composables/useModalFocusTrap'

const router=useRouter(),loading=ref(false),loadError=ref(''),accounts=ref<Account[]>([]),products=ref<MatrixProduct[]>([]),total=ref(0),page=ref(1),statusCounts=ref<Record<string,number>>({}),summary=ref<Record<string,any>>({}),notice=ref('')
const filter=reactive({search:'',accountId:undefined as number|undefined,statusBucket:'ALL',source:'',publishChannel:''})
const selectedKeys=ref<string[]>([]),savedFilters=ref<Array<Record<string,any>>>([]),batches=ref<Array<Record<string,any>>>([]),selected=ref<Record<string,any>|null>(null),detailLoading=ref(false),activeTab=ref<'basic'|'sku'|'marketing'|'metrics'|'timeline'>('basic')
const batchDialog=ref(false),batchLoading=ref(false),batchPreview=ref<Record<string,any>|null>(null),batch=reactive({operationType:'SYNC',selectionMode:'EXPLICIT' as 'EXPLICIT'|'FILTER_SNAPSHOT',value:'',speed:10,confirmationText:''})
const saveFilterDialog=ref(false),filterName=ref('')
useModalFocusTrap(batchDialog,()=>document.querySelector<HTMLElement>('.product-matrix .modal-card:not(.modal-card--small)'))
useModalFocusTrap(saveFilterDialog,()=>document.querySelector<HTMLElement>('.product-matrix .modal-card--small'))
const totalPages=computed(()=>Math.max(1,Math.ceil(total.value/20)))
const key=(p:MatrixProduct)=>`${p.accountId}:${p.goodsId}`,checked=(p:MatrixProduct)=>selectedKeys.value.includes(key(p))
const currentFilter=():ProductFilter=>({search:filter.search||undefined,accountIds:filter.accountId?[filter.accountId]:undefined,statusBucket:filter.statusBucket,source:filter.source||undefined,publishChannel:filter.publishChannel||undefined,page:page.value,pageSize:20})
const value=(v:unknown)=>v===null||v===undefined||v===''?'—':String(v),money=(v:unknown)=>v===null||v===undefined?'—':`¥ ${Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`,time=(v:unknown)=>v?new Date(String(v)).toLocaleString('zh-CN'):'—'
const label=(v?:string)=>({ALL:'全部',ON_SALE:'在售',SOLD:'已售出',OFF_SHELF:'已下架',OTHER:'其他',DRAFT:'草稿',FULL:'完整',PARTIAL:'部分',UNSYNCED:'未同步',SUCCEEDED:'成功',FAILED:'失败',UNKNOWN:'结果未知',SYNC:'同步',POLISH:'擦亮',ON_SALE_ACTION:'上架',OFF_SHELF_ACTION:'下架',CHANGE_PRICE:'改价',CHANGE_STOCK:'改库存',DELETE:'删除'}[v||'']||v||'未知')
const tone=(v?:string)=>['ON_SALE','FULL','SUCCEEDED'].includes(v||'')?'good':['FAILED','UNKNOWN','DELETE'].includes(v||'')?'bad':['PARTIAL','OFF_SHELF'].includes(v||'')?'warn':'muted'
const load=async()=>{loading.value=true;loadError.value='';try{const r=await queryProductMatrix(currentFilter());products.value=r.data?.records||[];total.value=r.data?.total||0;statusCounts.value=r.data?.statusCounts||{};summary.value=r.data?.summary||{};notice.value=r.data?.dataNotice||''}catch(e:any){loadError.value=e.message||'商品矩阵加载失败';showError(loadError.value)}finally{loading.value=false}}
const loadSupporting=async()=>{const [a,f,b]=await Promise.allSettled([getAccountList(),getSavedProductFilters(),getProductBatches()]);if(a.status==='fulfilled')accounts.value=a.value.data?.accounts||[];if(f.status==='fulfilled')savedFilters.value=f.value.data||[];if(b.status==='fulfilled')batches.value=b.value.data||[]}
const apply=()=>{page.value=1;void load()}
const toggle=(p:MatrixProduct)=>{selectedKeys.value=checked(p)?selectedKeys.value.filter(k=>k!==key(p)):[...selectedKeys.value,key(p)]}
const togglePage=()=>{const keys=products.value.map(key),all=keys.every(k=>selectedKeys.value.includes(k));selectedKeys.value=all?selectedKeys.value.filter(k=>!keys.includes(k)):[...new Set([...selectedKeys.value,...keys])]}
const openDetail=async(p:MatrixProduct)=>{detailLoading.value=true;activeTab.value='basic';try{const r=await getProductMatrixDetail(p.accountId,p.goodsId);selected.value=r.data||null}catch(e:any){showError(e.message||'商品详情加载失败')}finally{detailLoading.value=false}}
const applySaved=(item?:Record<string,any>)=>{if(!item)return;const f=item.filter||{};filter.search=f.search||'';filter.accountId=f.accountIds?.[0];filter.statusBucket=f.statusBucket||'ALL';filter.source=f.source||'';filter.publishChannel=f.publishChannel||'';apply()}
const saveCurrentFilter=async()=>{if(!filterName.value.trim())return showError('请输入筛选器名称');await saveProductFilter({name:filterName.value.trim(),filter:currentFilter(),requestId:newRequestId('filter')});filterName.value='';saveFilterDialog.value=false;showSuccess('筛选器已保存');await loadSupporting()}
const selectedRefs=()=>selectedKeys.value.map(item=>{const [accountId,goodsId]=item.split(':');return{accountId:Number(accountId),goodsId:goodsId!}})
const batchRequest=(confirm=''):ProductBatchRequest=>({requestId:newRequestId('product-batch'),operationType:batch.operationType,selectionMode:batch.selectionMode,items:batch.selectionMode==='EXPLICIT'?selectedRefs():undefined,filter:batch.selectionMode==='FILTER_SNAPSHOT'?{...currentFilter(),page:1,pageSize:500}:undefined,operationParams:batch.operationType==='CHANGE_PRICE'?{price:batch.value}:batch.operationType==='CHANGE_STOCK'?{stock:batch.value}:{},maxOperationsPerMinute:batch.speed,confirmationText:confirm})
const openBatch=()=>{if(!selectedKeys.value.length&&batch.selectionMode==='EXPLICIT')return showError('请先选择商品，或改用“当前筛选结果”');batchPreview.value=null;batch.confirmationText='';batchDialog.value=true}
const previewBatch=async()=>{batchLoading.value=true;try{const r=await previewProductBatch(batchRequest());batchPreview.value=r.data||null}catch(e:any){showError(e.message||'批量预检失败')}finally{batchLoading.value=false}}
const executeBatch=async()=>{if(!batchPreview.value)return;if(batch.confirmationText!==batchPreview.value.confirmationSummary)return showError('请输入完整确认文案');batchLoading.value=true;try{const r=await createProductBatch(batchRequest(batch.confirmationText));showSuccess(`批量任务已创建：${r.data?.batchId||r.data?.jobId||'已入队'}`);batchDialog.value=false;selectedKeys.value=[];await Promise.all([load(),loadSupporting()])}finally{batchLoading.value=false}}
onMounted(async()=>{await loadSupporting();void load()})
</script>

<template>
  <main class="workbench product-matrix" :aria-busy="loading"><header class="workbench__header"><div><h1>商品矩阵</h1><p>跨店管理商品事实、同步覆盖、运营配置和可恢复批量任务。</p></div><div class="workbench__actions"><button class="workbench__btn" @click="router.push('/product-publish')">发布商品</button><button class="workbench__btn" @click="saveFilterDialog=true">保存筛选</button><button class="workbench__btn workbench__btn--primary" @click="openBatch">批量操作{{ selectedKeys.length?`（${selectedKeys.length}）`:'' }}</button></div></header>
    <section class="product-matrix__metrics"><article><span>当前页商品</span><strong>{{ summary.productCount??'—' }}</strong><small>总计 {{ total }}</small></article><article><span>平均价格</span><strong>{{ money(summary.averagePrice) }}</strong><small>已知价格 {{ summary.knownPriceCount??'—' }} 件</small></article><article><span>已知库存</span><strong>{{ summary.totalStock??'—' }}</strong><small>{{ summary.knownStockCount??'—' }} 件有库存证据</small></article><article><span>在售</span><strong>{{ statusCounts.ON_SALE??'—' }}</strong><small>跨全部筛选结果</small></article><article><span>未同步</span><strong>{{ summary.unsyncedCount??'—' }}</strong><small>不会伪装成平台状态</small></article></section>
    <div class="product-matrix__notice"><strong>数据说明</strong><span>{{ notice||'每行显示来源、覆盖度和最近同步时间。' }}</span></div>
    <section class="workbench__card product-matrix__panel"><div class="product-matrix__toolbar"><input v-model="filter.search" class="workbench__input" placeholder="商品标题、ID 或店铺备注" @keyup.enter="apply"><select v-model="filter.accountId" class="workbench__select" @change="apply"><option :value="undefined">全部可见店铺</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.accountNote||a.unb }}</option></select><select v-model="filter.source" class="workbench__select" @change="apply"><option value="">全部数据来源</option><option value="PLATFORM_API">平台接口</option><option value="PLATFORM_WEB">平台页面</option><option value="LOCAL">本地</option><option value="MANUAL_IMPORT">人工导入</option></select><select v-model="filter.publishChannel" class="workbench__select" @change="apply"><option value="">全部发布通道</option><option value="PLATFORM_API">平台接口</option><option value="PLATFORM_WEB">平台页面</option><option value="LOCAL_ONLY">仅本地</option></select><button class="workbench__btn" @click="apply">查询</button></div>
      <div class="product-matrix__tabs"><button v-for="s in ['ALL','ON_SALE','SOLD','OFF_SHELF','OTHER','DRAFT']" :key="s" :class="{active:filter.statusBucket===s}" @click="filter.statusBucket=s;apply()">{{ label(s) }} <span>{{ statusCounts[s]??'—' }}</span></button><select class="saved-filter" aria-label="已保存筛选器" @change="applySaved(savedFilters[Number(($event.target as HTMLSelectElement).value)])"><option value="">已保存筛选器</option><option v-for="(f,index) in savedFilters" :key="f.id" :value="index">{{ f.name }}</option></select></div>
      <div v-if="loading" class="product-matrix__state" role="status" aria-live="polite"><span class="product-matrix__spinner" aria-hidden="true"></span><div><strong>正在加载商品数据</strong><small>已保留当前筛选条件，请稍候。</small></div></div><div v-else-if="loadError" class="product-matrix__state product-matrix__state--error" role="alert"><div><strong>商品数据暂时无法读取</strong><small>{{ loadError }}</small></div><button class="workbench__btn" @click="load">重新加载</button></div>
      <div class="product-matrix__table"><table><thead><tr><th><input type="checkbox" :checked="products.length>0&&products.every(checked)" aria-label="选择当前页全部商品" @change="togglePage"></th><th>商品 / 店铺</th><th>价格 / 库存</th><th>平台状态</th><th>发布来源</th><th>同步证据</th><th></th></tr></thead><tbody><tr v-for="p in products" :key="key(p)" :class="{selected:checked(p)}" @click="openDetail(p)"><td><input type="checkbox" :checked="checked(p)" :aria-label="`选择商品 ${p.title}`" @click.stop @change="toggle(p)"></td><td><div class="product-cell"><img v-if="p.coverPic" :src="p.coverPic" alt=""><div v-else class="product-cell__image">图</div><span><strong>{{ p.title||p.goodsId }}</strong><small>{{ p.accountNote||`店铺 ${p.accountId}` }} · ID {{ p.goodsId }}</small></span></div></td><td><strong>{{ money(p.price) }}</strong><small>库存 {{ p.stock??'—' }} · SKU {{ p.skuCount??'—' }}</small></td><td><span :class="['status',tone(p.statusBucket)]">{{ label(p.statusBucket) }}</span></td><td><strong>{{ p.source||'NONE' }}</strong><small>{{ p.publishChannel||'发布通道未知' }}</small></td><td><span :class="['status',tone(p.coverageStatus)]">{{ label(p.coverageStatus) }}</span><small>{{ time(p.lastSyncedTime) }}</small><em v-if="p.lastSyncErrorMessage">{{ p.lastSyncErrorMessage }}</em></td><td><button class="row-action" @click.stop="openDetail(p)">360° 详情</button></td></tr></tbody></table><div v-if="!loading&&!loadError&&!products.length" class="product-matrix__empty">当前范围没有商品。</div></div><footer class="product-matrix__pagination"><span>已选择 {{ selectedKeys.length }} 件 · 共 {{ total }} 件</span><div><button :disabled="loading||page<=1" @click="page--;load()">上一页</button><b>{{ page }} / {{ totalPages }}</b><button :disabled="loading||page>=totalPages" @click="page++;load()">下一页</button></div></footer></section>
    <section v-if="batches.length" class="workbench__card product-matrix__jobs"><div><h2>最近批量任务</h2><p>失败和结果未知会保留逐件记录，不盲目重复执行。</p></div><div class="job-list"><article v-for="j in batches.slice(0,5)" :key="j.jobId"><strong>{{ label(j.operationType) }} · {{ j.selectedCount }} 件</strong><span :class="['status',tone(j.status)]">{{ label(j.status) }}</span><small>成功 {{ j.successCount }} / 失败 {{ j.failedCount }} / 未知 {{ j.unknownCount }}</small></article></div></section>
    <div v-if="selected||detailLoading" class="product-drawer__backdrop" @click.self="selected=null"><aside class="product-drawer" role="dialog" aria-modal="true" aria-labelledby="product-title"><div v-if="detailLoading" class="product-matrix__empty">正在读取商品档案…</div><template v-else-if="selected"><header><div class="product-drawer__identity"><img v-if="selected.basic.coverPic" :src="selected.basic.coverPic" alt=""><div><h2 id="product-title">{{ selected.basic.title||selected.basic.goodsId }}</h2><p>{{ selected.basic.accountNote }} · 商品 ID {{ selected.basic.goodsId }}</p></div></div><button aria-label="关闭" @click="selected=null">×</button></header><nav><button v-for="t in [{k:'basic',n:'基本信息'},{k:'sku',n:`SKU ${selected.skus?.length||0}`},{k:'marketing',n:'营销'},{k:'metrics',n:'数据罗盘'},{k:'timeline',n:`事件 ${selected.timeline?.length||0}`} ]" :key="t.k" :class="{active:activeTab===t.k}" @click="activeTab=t.k as any">{{ t.n }}</button></nav><div class="product-drawer__body"><template v-if="activeTab==='basic'"><div class="product-facts"><div><span>售价</span><strong>{{ money(selected.basic.price) }}</strong></div><div><span>库存</span><strong>{{ value(selected.basic.stock) }}</strong></div><div><span>平台状态</span><strong>{{ label(selected.basic.statusBucket) }}</strong></div><div><span>同步覆盖</span><strong>{{ label(selected.basic.coverageStatus) }}</strong></div></div><section class="drawer-card"><h3>商品描述与分类</h3><p>{{ selected.basic.detailJson||'描述未同步' }}</p><dl><div><dt>类目</dt><dd>{{ value(selected.basic.categoryName||selected.basic.categoryId) }}</dd></div><div><dt>商品类型</dt><dd>{{ value(selected.basic.itemType) }}</dd></div><div><dt>经营模式</dt><dd>{{ value(selected.basic.businessMode) }}</dd></div><div><dt>运费</dt><dd>{{ selected.basic.shippingType||money(selected.basic.shippingFee) }}</dd></div></dl></section></template><template v-else-if="activeTab==='sku'"><section class="drawer-card"><div v-if="selected.skus?.length" class="sku-list"><article v-for="sku in selected.skus" :key="sku.skuId||sku.skuKey"><strong>{{ sku.skuText||sku.skuKey }}</strong><span>{{ money(sku.price) }}</span><small>库存 {{ sku.stock??'—' }} · 平台状态 {{ sku.platformStatus??'—' }}</small></article></div><p v-else>没有已同步 SKU 子项，不能据此判断为 0 个平台规格。</p></section></template><template v-else-if="activeTab==='marketing'"><section class="drawer-card"><h3>本地自动化</h3><div class="capability-grid"><article v-for="(enabled,k) in {自动发货:selected.marketing.autoDeliveryEnabled,自动回复:selected.marketing.autoReplyEnabled,自动评价:selected.marketing.autoRateEnabled,自动擦亮:selected.marketing.autoPolishEnabled}" :key="k"><strong>{{ k }}</strong><span :class="['status',enabled?'good':'muted']">{{ enabled?'已开启':'已关闭' }}</span></article></div><h3>平台营销</h3><p>粉丝价 {{ value(selected.marketing.fanPrice) }} · 小刀 {{ value(selected.marketing.bargain) }} · 闲鱼币抵扣 {{ value(selected.marketing.coinDeduction) }}</p><small>{{ label(selected.marketing.marketingCoverageStatus) }}，未接通时不提供假设置入口。</small></section></template><template v-else-if="activeTab==='metrics'"><div class="metric-window" v-for="(m,k) in selected.metrics" :key="k"><header><strong>{{ k }}</strong><span :class="['status',tone(m.coverageStatus)]">{{ label(m.coverageStatus) }}</span></header><div><span>曝光<strong>{{ value(m.exposureCount) }}</strong></span><span>访客<strong>{{ value(m.visitorCount) }}</strong></span><span>咨询<strong>{{ value(m.inquiryCount) }}</strong></span><span>支付<strong>{{ value(m.paidOrderCount) }}</strong></span></div><small>{{ m.sampleDays||0 }} 天样本 · {{ time(m.syncedAt) }}</small></div></template><template v-else><ol class="timeline"><li v-for="event in selected.timeline" :key="event.eventId"><i></i><div><strong>{{ event.eventType }}</strong><p>{{ event.outcomeState }} · {{ event.dataSource }} · {{ event.operatorUsername||'系统' }}</p><small>{{ time(event.createdTime) }} · 请求 {{ event.requestId||'—' }}</small></div></li></ol></template></div><footer><button class="workbench__btn" @click="router.push({path:'/auto-delivery',query:{accountId:selected.basic.accountId,goodsId:selected.basic.goodsId}})">发货配置</button><button class="workbench__btn" @click="router.push({path:'/auto-reply',query:{accountId:selected.basic.accountId,goodsId:selected.basic.goodsId}})">回复配置</button><button class="workbench__btn workbench__btn--primary" @click="selected=null">完成查看</button></footer></template></aside></div>
    <div v-if="batchDialog" class="modal-backdrop" @click.self="batchDialog=false"><section class="modal-card"><header><div><h2>批量操作预检</h2><p>范围、冲突、速率和确认文案都必须在执行前明确。</p></div><button aria-label="关闭" @click="batchDialog=false">×</button></header><div class="modal-body"><label>操作<select v-model="batch.operationType" class="workbench__select"><option value="SYNC">同步</option><option value="POLISH">擦亮</option><option value="ON_SALE">上架</option><option value="OFF_SHELF">下架</option><option value="CHANGE_PRICE">改价</option><option value="CHANGE_STOCK">改库存</option><option value="DELETE">删除（高风险）</option></select></label><label>选择范围<select v-model="batch.selectionMode" class="workbench__select"><option value="EXPLICIT">已勾选的 {{ selectedKeys.length }} 件</option><option value="FILTER_SNAPSHOT">当前筛选结果（最多500件）</option></select></label><label v-if="['CHANGE_PRICE','CHANGE_STOCK'].includes(batch.operationType)">{{ batch.operationType==='CHANGE_PRICE'?'新价格':'新库存' }}<input v-model="batch.value" class="workbench__input" type="number" min="0"></label><label>每分钟最大操作数<input v-model.number="batch.speed" class="workbench__input" type="number" min="1" max="60"></label><button class="workbench__btn" :disabled="batchLoading" @click="previewBatch">运行预检</button><section v-if="batchPreview" class="batch-preview"><div><span>店铺</span><strong>{{ batchPreview.accountCount }}</strong></div><div><span>商品</span><strong>{{ batchPreview.selectedCount }}</strong></div><div><span>可执行</span><strong>{{ batchPreview.executableCount }}</strong></div><div><span>冲突</span><strong>{{ batchPreview.conflictCount }}</strong></div><p>{{ batchPreview.confirmationSummary }}</p><label>输入完整确认文案<input v-model="batch.confirmationText" class="workbench__input"></label></section></div><footer><button class="workbench__btn" @click="batchDialog=false">取消</button><button class="workbench__btn workbench__btn--primary" :disabled="!batchPreview||batch.confirmationText!==batchPreview.confirmationSummary||batchLoading" @click="executeBatch">确认创建任务</button></footer></section></div>
    <div v-if="saveFilterDialog" class="modal-backdrop" @click.self="saveFilterDialog=false"><section class="modal-card modal-card--small" role="dialog" aria-modal="true" aria-labelledby="save-filter-title"><header><div><h2 id="save-filter-title">保存当前筛选</h2><p>保存的是筛选条件，不会冻结或复制商品。</p></div><button aria-label="关闭" @click="saveFilterDialog=false">×</button></header><div class="modal-body"><label>名称<input v-model="filterName" class="workbench__input" maxlength="80"></label></div><footer><button class="workbench__btn" @click="saveFilterDialog=false">取消</button><button class="workbench__btn workbench__btn--primary" @click="saveCurrentFilter">保存</button></footer></section></div>
  </main>
</template>
<style scoped src="./goods.css"></style>
<style scoped>
.product-matrix__state { display: flex; align-items: center; gap: 10px; justify-content: flex-start; margin: 10px 14px 0; padding: 12px 14px; border: 1px solid #eed47a; border-radius: 10px; background: #fffaf0; color: #715100; }
.product-matrix__state > div { display: grid; flex: 1; gap: 3px; }
.product-matrix__state small { color: #77736b; }
.product-matrix__state--error { border-color: #f0b2aa; background: #fff4f2; color: #b42318; }
.product-matrix__spinner { width: 15px; height: 15px; flex: 0 0 15px; border: 2px solid #e3d8ad; border-top-color: #8a5a00; border-radius: 50%; animation: product-matrix-spin .7s linear infinite; }
@keyframes product-matrix-spin { to { transform: rotate(360deg); } }
@media (max-width: 767px) {
  .product-matrix__metrics { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); overflow: visible; }
  .product-matrix__metrics article { min-width: 0; }
  .product-matrix__state { align-items: flex-start; flex-wrap: wrap; }
}
</style>
